export const emacsHandbookHtml = "<style>\n\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: 1.5em;}\ndiv.column{flex: auto;}\n@media screen {\ndiv.columns{gap: min(4vw, 1.5em);}\ndiv.column{overflow-x: auto;}\n}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type=\"checkbox\"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n.display.math{display: block; text-align: center; margin: 0.5rem auto;}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ff0000; font-weight: bold; }\ncode span.an { color: #60a0b0; font-weight: bold; font-style: italic; }\ncode span.at { color: #7d9029; }\ncode span.bn { color: #40a070; }\ncode span.bu { color: #008000; }\ncode span.cf { color: #007020; font-weight: bold; }\ncode span.ch { color: #4070a0; }\ncode span.cn { color: #880000; }\ncode span.co { color: #60a0b0; font-style: italic; }\ncode span.cv { color: #60a0b0; font-weight: bold; font-style: italic; }\ncode span.do { color: #ba2121; font-style: italic; }\ncode span.dt { color: #902000; }\ncode span.dv { color: #40a070; }\ncode span.er { color: #ff0000; font-weight: bold; }\ncode span.ex { }\ncode span.fl { color: #40a070; }\ncode span.fu { color: #06287e; }\ncode span.im { color: #008000; font-weight: bold; }\ncode span.in { color: #60a0b0; font-weight: bold; font-style: italic; }\ncode span.kw { color: #007020; font-weight: bold; }\ncode span.op { color: #666666; }\ncode span.ot { color: #007020; }\ncode span.pp { color: #bc7a00; }\ncode span.sc { color: #4070a0; }\ncode span.ss { color: #bb6688; }\ncode span.st { color: #4070a0; }\ncode span.va { color: #19177c; }\ncode span.vs { color: #4070a0; }\ncode span.wa { color: #60a0b0; font-weight: bold; font-style: italic; }\n</style>\n<style>:root {\ncolor-scheme: light dark;\nfont-family: Georgia, \"Times New Roman\", serif;\nline-height: 1.6;\nbackground: #f5f1e8;\ncolor: #29251f;\n}\nbody {\nbox-sizing: border-box;\nmax-width: 52rem;\nmargin: 0 auto;\npadding: 4.75rem 2rem 6rem;\nbackground: #fffdf8;\nbox-shadow: 0 0 0 1px rgb(74 63 49 / 10%);\n}\nh1,\nh2,\nh3,\nh4 {\ncolor: #30271e;\nfont-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\nline-height: 1.2;\ntext-wrap: balance;\n}\nh1 {\nmargin-top: 0;\nfont-size: clamp(2rem, 6vw, 3.25rem);\n}\nh2 {\nmargin-top: 2.75rem;\npadding-top: 0.75rem;\nborder-top: 1px solid rgb(74 63 49 / 18%);\n}\na {\ncolor: #7d3f17;\ntext-underline-offset: 0.16em;\n}\ncode,\npre {\nfont-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n}\ncode {\noverflow-wrap: anywhere;\n}\npre {\noverflow-x: auto;\npadding: 1rem;\nborder: 1px solid rgb(74 63 49 / 16%);\nborder-radius: 0.5rem;\nbackground: #f2ede3;\n}\ntable {\ndisplay: block;\nwidth: max-content;\nmax-width: 100%;\noverflow-x: auto;\nborder-collapse: collapse;\n}\nth,\ntd {\npadding: 0.45rem 0.65rem;\nborder: 1px solid rgb(74 63 49 / 20%);\ntext-align: left;\nvertical-align: top;\n}\nblockquote {\nmargin-left: 0;\npadding-left: 1rem;\nborder-left: 0.25rem solid #b66b36;\ncolor: #574b40;\n}\nimg {\nmax-width: 100%;\nheight: auto;\n}\n@media (max-width: 40rem) {\nbody {\npadding: 4.5rem 1.1rem 4rem;\n}\n}\n@media (prefers-color-scheme: dark) {\n:root {\nbackground: #171512;\ncolor: #ede5d8;\n}\nbody {\nbackground: #201d19;\nbox-shadow: 0 0 0 1px rgb(255 255 255 / 8%);\n}\nh1,\nh2,\nh3,\nh4 {\ncolor: #fff8ea;\n}\na {\ncolor: #e8a66e;\n}\npre {\nborder-color: rgb(255 255 255 / 12%);\nbackground: #171512;\n}\nth,\ntd {\nborder-color: rgb(255 255 255 / 14%);\n}\nblockquote {\ncolor: #cfc2b2;\n}\n}\n@media print {\n:root,\nbody {\nbackground: #fff;\ncolor: #000;\n}\nbody {\nmax-width: none;\npadding: 0;\nbox-shadow: none;\n}\n}\n</style>\n\n<header id=\"title-block-header\">\n<h1 class=\"title\">The FirstPair Guide to Reading Books in Emacs</h1>\n</header>\n<p><a href=\"https://firstpair.org/\">← First Pair library</a></p>\n<section id=\"the-firstpair-guide-to-reading-books-in-emacs\" class=\"level1\">\n<h1>The FirstPair Guide to Reading Books in Emacs</h1>\n<p>A FirstPair Emacs bundle is a folder holding a book as a GNU Info\nmanual, a second manual of the sources and records the book points at,\nthe tables that connect the two, an offline dictionary, and the Texinfo\nsource of both manuals. FirstPair uses the format because Info is the\noldest hypertext still in daily use: it reads on any machine that runs\nEmacs, it needs no network, no account, and no browser, and it keeps a\nreader’s place with nothing more than the keyboard.</p>\n<p>You own the downloaded files. The book remains readable with the\nstandalone <code>info</code> program, with Emacs alone, or after\nre-rendering the Texinfo source into HTML, PDF, or plain text. Nothing\nin the bundle contacts a server.</p>\n<section id=\"install-emacs\" class=\"level2\">\n<h2>Install Emacs</h2>\n<ol type=\"1\">\n<li>Install GNU Emacs 27.1 or newer. On macOS,\n<code>brew install --cask emacs</code> or the build at <a href=\"https://emacsformacosx.com/\">emacsformacosx.com</a>; on Windows,\nthe release from <a href=\"https://www.gnu.org/software/emacs/\">gnu.org/software/emacs</a>;\non Linux, your distribution’s <code>emacs</code> package.</li>\n<li>Download the bundle ZIP from the book’s FirstPair page.</li>\n<li>Extract the ZIP completely. Do not open files while they are still\ninside the archive.</li>\n<li>Note the extracted folder’s location. It contains\n<code>init.el</code>, <code>Guide.md</code>, two <code>.info</code>\nfiles, and the <code>lisp/</code>, <code>data/</code>,\n<code>lexicon/</code>, and <code>texi/</code> folders.</li>\n</ol>\n<p>Keep the ZIP until you have verified the bundle. It is a clean\nrecovery copy.</p>\n</section>\n<section id=\"open-the-book\" class=\"level2\">\n<h2>Open the book</h2>\n<p>Start Emacs, then load the bundle’s loader once:</p>\n<pre class=\"text\"><code>M-x load-file RET /path/to/the/bundle/init.el RET</code></pre>\n<p><code>M-x</code> is <code>Alt+x</code> (or <code>Esc</code> then\n<code>x</code>), and <code>RET</code> is the Return key. Then:</p>\n<pre class=\"text\"><code>M-x firstpair-read RET</code></pre>\n<p>The frame divides into two windows. The book opens in the upper\nwindow at its Top node with the contents menu. The lower window shows\nthe Top node of the references manual. A third window for the dictionary\nappears the first time you look a word up.</p>\n<p>To make the bundle available every time Emacs starts, add one line to\nyour Emacs configuration file (<code>~/.emacs.d/init.el</code> or\n<code>~/.config/emacs/init.el</code>):</p>\n<pre class=\"elisp\"><code>(load &quot;/path/to/the/bundle/init.el&quot;)</code></pre>\n</section>\n<section id=\"install-the-reader-once-for-every-firstpair-book\" class=\"level2\">\n<h2>Install the reader once, for every FirstPair book</h2>\n<p>Each bundle carries its own copy of the reader, so the step above is\nall a single book needs. If you read several FirstPair books, install\nthe reader as an Emacs package instead and let it find your bundles:</p>\n<pre class=\"elisp\"><code>;; From a downloaded firstpair-reader-&lt;version&gt;.tar:\nM-x package-install-file RET /path/to/firstpair-reader-1.3.tar RET\n\n;; Or straight from the FirstPair repository (Emacs 29 or newer):\n(package-vc-install &#39;(firstpair-reader\n                      :url &quot;https://github.com/firstpair/firstpair&quot;\n                      :lisp-dir &quot;publishing/emacs/lisp&quot;))</code></pre>\n<p>Then tell it where your bundles live and open one:</p>\n<pre class=\"elisp\"><code>(setq firstpair-reader-bundle-directories &#39;(&quot;~/Books/FirstPair&quot;))\nM-x firstpair-read RET</code></pre>\n<p><code>firstpair-read</code> registers every bundle found in those\nfolders and offers a choice when there is more than one. A bundle’s\n<code>init.el</code> still works and, when the package is installed,\nuses the installed reader rather than its own copy. The package also\ninstalls this handbook as an Info manual:\n<code>C-h i m FirstPair Reader RET</code>.</p>\n</section>\n<section id=\"your-first-five-minutes\" class=\"level2\">\n<h2>Your first five minutes</h2>\n<p>Everything is ordinary Info. The keys you need:</p>\n<table>\n<thead>\n<tr>\n<th>Key</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>SPC</code> / <code>DEL</code></td>\n<td>scroll forward / back, continuing into the next node</td>\n</tr>\n<tr>\n<td><code>n</code> / <code>p</code></td>\n<td>next / previous node at the same level</td>\n</tr>\n<tr>\n<td><code>u</code></td>\n<td>up to the containing part or the Top node</td>\n</tr>\n<tr>\n<td><code>RET</code></td>\n<td>follow the menu item or reference under the cursor</td>\n</tr>\n<tr>\n<td><code>l</code></td>\n<td>back to where you were before the last jump</td>\n</tr>\n<tr>\n<td><code>t</code></td>\n<td>the Top node of the current manual</td>\n</tr>\n<tr>\n<td><code>m</code></td>\n<td>pick a menu item by name</td>\n</tr>\n<tr>\n<td><code>g</code></td>\n<td>go to a node by name</td>\n</tr>\n<tr>\n<td><code>s</code></td>\n<td>search the whole manual</td>\n</tr>\n<tr>\n<td><code>q</code></td>\n<td>leave Info; <code>M-x firstpair-read</code> returns</td>\n</tr>\n<tr>\n<td><code>C-h m</code></td>\n<td>list every key that works here</td>\n</tr>\n</tbody>\n</table>\n<p><code>C-h m</code> means hold Control, press <code>h</code>, release,\npress <code>m</code>. Use the mouse if you prefer: menu items and\nreferences are clickable.</p>\n<p>Reading order runs through the Top node’s menu: the contents, then\neach part, then the guide you are reading now, then the colophon.\n<code>SPC</code> at the end of a chapter continues into the next one, so\na book can be read start to finish with one key.</p>\n<p>You cannot damage the edition by exploring. Info never writes to its\nfiles.</p>\n</section>\n<section id=\"references-open-below-the-text\" class=\"level2\">\n<h2>References open below the text</h2>\n<p>A cited passage in the book is followed by a citation in parentheses,\nshown as “(see Letters to Atticus 1.17.6)”. Press <code>RET</code> on\nit, or click it, and the record opens in the lower window: the original\ntext, the translation, its witness and translator, its rights, and a\n<strong>Quoted in</strong> list pointing back to every chapter that uses\nit. The upper window does not move.</p>\n<p>The lower window is a complete Info manual of its own.\n<code>n</code>, <code>p</code>, <code>u</code>, and <code>s</code> work\nthere; <code>RET</code> on a <strong>Quoted in</strong> entry brings\nthat chapter back into the upper window. <code>C-c C-o</code> moves the\ncursor between the windows; <code>C-x o</code> also works.</p>\n<p>Two keys reach references without hunting for the citation:</p>\n<table>\n<colgroup>\n<col style=\"width: 50%\" />\n<col style=\"width: 50%\" />\n</colgroup>\n<thead>\n<tr>\n<th>Key</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>C-c C-r</code></td>\n<td>choose among the references quoted in the current chapter</td>\n</tr>\n<tr>\n<td><code>C-c C-f</code></td>\n<td>open the file delivered for the reference shown below</td>\n</tr>\n</tbody>\n</table>\n<p><code>C-c C-f</code> matters for evidence that is a file rather than\ntext: an image, a transcription, a data table. It opens inside Emacs, in\nthe lower window, and <code>q</code> returns to the reference.</p>\n</section>\n<section id=\"the-dictionary-window\" class=\"level2\">\n<h2>The dictionary window</h2>\n<p>Words the bundle’s lexicon can explain are underlined. Hover the\nmouse over one to see a one-line gloss, or use the keys:</p>\n<table>\n<colgroup>\n<col style=\"width: 50%\" />\n<col style=\"width: 50%\" />\n</colgroup>\n<thead>\n<tr>\n<th>Key</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>C-c C-d</code></td>\n<td>look up the word under the cursor</td>\n</tr>\n<tr>\n<td><code>C-c C-n</code> / <code>C-c C-p</code></td>\n<td>move to the next / previous underlined word</td>\n</tr>\n<tr>\n<td><code>C-c C-g</code></td>\n<td>open the glossary of every explained word in this edition</td>\n</tr>\n</tbody>\n</table>\n<p>The entry shows the dictionary form, the grammatical analysis of the\nexact form in front of you, and the senses. Lookup is a table read from\nthe bundle’s <code>lexicon/</code> folder; it works with no network and\nno external program. <code>C-c C-d</code> also works on words that are\nnot underlined, and reports honestly when the lexicon has no entry.</p>\n<p>Set <code>firstpair-reader-highlight</code> to <code>nil</code> in\nyour configuration to turn the underlines off while keeping every\nkey.</p>\n</section>\n<section id=\"rearranging-windows\" class=\"level2\">\n<h2>Rearranging windows</h2>\n<p><code>C-c C-l</code> restores the standard layout: book above,\nreferences below, dictionary under both. The customisation variables\n<code>firstpair-reader-references-height</code> (a fraction of the\nframe) and <code>firstpair-reader-lexicon-height</code> (a number of\nlines) adjust the proportions. You may also drag the divider between\nwindows.</p>\n</section>\n<section id=\"reading-without-the-firstpair-reader\" class=\"level2\">\n<h2>Reading without the FirstPair reader</h2>\n<p>The manuals do not depend on the reader. In plain Emacs:</p>\n<pre class=\"text\"><code>C-u C-h i /path/to/the/bundle/&lt;book&gt;.info RET</code></pre>\n<p>or, in a terminal:</p>\n<div class=\"sourceCode\" id=\"cb7\"><pre class=\"sourceCode sh\"><code class=\"sourceCode bash\"><span id=\"cb7-1\"><a href=\"#cb7-1\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"ex\">info</span> <span class=\"at\">-f</span> /path/to/the/bundle/<span class=\"op\">&lt;</span>book<span class=\"op\">&gt;</span>.info</span></code></pre></div>\n<p>Citations still work; they open in the same window, and\n<code>l</code> returns. The manual name appears after the label, as Info\nshows any reference to another manual. The dictionary keys are not\navailable without the reader.</p>\n</section>\n<section id=\"add-the-manuals-to-infos-directory\" class=\"level2\">\n<h2>Add the manuals to Info’s directory</h2>\n<p><code>M-x firstpair-read</code> never touches your system. If you\nwould rather find the book under <code>C-h i</code> or the\n<code>info</code> command beside the Emacs and GNU manuals, install its\ntwo manuals into an Info directory:</p>\n<div class=\"sourceCode\" id=\"cb8\"><pre class=\"sourceCode sh\"><code class=\"sourceCode bash\"><span id=\"cb8-1\"><a href=\"#cb8-1\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"ex\">./install.sh</span>                      <span class=\"co\"># into ~/.local/share/info</span></span>\n<span id=\"cb8-2\"><a href=\"#cb8-2\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"ex\">./install.sh</span> /usr/local/share/info</span>\n<span id=\"cb8-3\"><a href=\"#cb8-3\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"ex\">./install.sh</span> <span class=\"at\">--remove</span>             <span class=\"co\"># take them out again</span></span></code></pre></div>\n<p>or, inside Emacs, <code>M-x firstpair-reader-install-info</code> (and\n<code>firstpair-reader-uninstall-info</code>). Both copy the\n<code>.info</code> files and update the directory’s <code>dir</code>\nmenu, using GNU <code>install-info</code> when it is present and Emacs\nitself otherwise. Then add the directory to Emacs:</p>\n<pre class=\"elisp\"><code>(add-to-list &#39;Info-directory-list &quot;~/.local/share/info&quot;)</code></pre>\n<p>or to your shell,\n<code>export INFOPATH=&quot;$HOME/.local/share/info:&quot;</code>, and the book\nappears under <strong>Books</strong> in the Info directory. Reading it\nthat way is plain Info: the FirstPair keys need the reader loaded as\nabove.</p>\n</section>\n<section id=\"re-rendering-the-edition\" class=\"level2\">\n<h2>Re-rendering the edition</h2>\n<p>The <code>texi/</code> folder holds the Texinfo source of both\nmanuals, generated from the same document model as the Info files. With\nGNU Texinfo installed:</p>\n<div class=\"sourceCode\" id=\"cb10\"><pre class=\"sourceCode sh\"><code class=\"sourceCode bash\"><span id=\"cb10-1\"><a href=\"#cb10-1\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"ex\">makeinfo</span> <span class=\"at\">--html</span> <span class=\"at\">--no-split</span> texi/<span class=\"op\">&lt;</span>book<span class=\"op\">&gt;</span>.texi</span>\n<span id=\"cb10-2\"><a href=\"#cb10-2\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"ex\">makeinfo</span> <span class=\"at\">--plaintext</span> texi/<span class=\"op\">&lt;</span>book<span class=\"op\">&gt;</span>.texi <span class=\"op\">&gt;</span> <span class=\"op\">&lt;</span>book<span class=\"op\">&gt;</span>.txt</span>\n<span id=\"cb10-3\"><a href=\"#cb10-3\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"ex\">texi2pdf</span> texi/<span class=\"op\">&lt;</span>book<span class=\"op\">&gt;</span>.texi</span></code></pre></div>\n<p>The output is the same book in another form. Cross-references between\nthe two manuals remain references to the companion manual.</p>\n</section>\n<section id=\"make-personal-notes-without-fighting-updates\" class=\"level2\">\n<h2>Make personal notes without fighting updates</h2>\n<p>Treat the <code>.info</code>, <code>data/</code>,\n<code>lexicon/</code>, and <code>texi/</code> files as edition material.\nEmacs bookmarks (<code>C-x r m</code> inside a node,\n<code>C-x r b</code> to return) record your place without touching the\nbundle. Keep durable notes in a separate file of your own; Org mode\nlinks of the form <code>[[info:&lt;book&gt;#Node Name]]</code> point\nback into the book.</p>\n</section>\n<section id=\"updating-a-firstpair-bundle\" class=\"level2\">\n<h2>Updating a FirstPair bundle</h2>\n<ol type=\"1\">\n<li>Download and verify the new versioned ZIP.</li>\n<li>Extract it beside the old folder, not over it.</li>\n<li>Change the path in your configuration, or load the new\n<code>init.el</code>, and restart Emacs so the old bundle is\nforgotten.</li>\n<li>Open the new edition and confirm the Top node, a citation, and a\ndictionary lookup.</li>\n<li>Retain the old folder until the replacement has survived a full\nrestart.</li>\n</ol>\n<p>Bookmarks and Org links are tied to node names, which stay stable\nbetween editions unless a chapter is retitled.</p>\n</section>\n<section id=\"troubleshooting\" class=\"level2\">\n<h2>Troubleshooting</h2>\n<p>If <code>M-x firstpair-read</code> reports that no bundle is\nregistered, the loader has not run: <code>M-x load-file</code> the\nbundle’s <code>init.el</code>.</p>\n<p>If Info reports that it cannot find the manual, the bundle folder was\nmoved after <code>init.el</code> was loaded. Load <code>init.el</code>\nagain from its new place.</p>\n<p>If references open in the upper window and replace the text, the\nreader is inactive in that buffer: press <code>q</code> and start again\nwith <code>M-x firstpair-read</code>.</p>\n<p>If words are not underlined, check that\n<code>firstpair-reader-highlight</code> is non-nil and that the\n<code>data/marked.tsv</code> and <code>lexicon/</code> files extracted\ncompletely.</p>\n<p>If a citation opens the wrong record, note the book version, the\nchapter, the visible citation, and the destination, and report it. Do\nnot edit the Info files as a permanent repair; the next edition is\nregenerated from source.</p>\n</section>\n<section id=\"a-durable-mental-model\" class=\"level2\">\n<h2>A durable mental model</h2>\n<p>The upper window is the book. The lower window is the library: every\nsource and record the book stands on, one node each. The dictionary\nwindow is the desk reference. <code>l</code> is your thread back through\nthe labyrinth. Bookmarks and your own notes are your work, and live\noutside the bundle. With those boundaries an Emacs bundle remains\napproachable for a first-time reader while holding the depth a scholar\nor a programmer expects.</p>\n</section>\n</section>\n"
